package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StdDateFormat_isLenient_TriageGen2Test {







    @Test
    public void testIsLenient_ViaSetter() {
        // Test the transition from default (null/false) to true using the public setter
        StdDateFormat df = new StdDateFormat();
        // Initial state check (based on implementation logic where null -> false)
        assertFalse(df.isLenient());

        df.setLenient(true);
        assertTrue("After calling setLenient(true), isLenient() should return true", df.isLenient());

        df.setLenient(false);
        assertFalse("After calling setLenient(false), isLenient() should return false", df.isLenient());
    }
}
